INSERT INTO TBL_REVIEW (REVIEW_ID, RESERVATION_ID, RATING, CONTENT, CREATED_AT, REPLY_CONTENT, REPLIED_AT, ADMIN_ID) VALUES (900001, 900001, 5, '포장부터 정리까지 정말 꼼꼼하게 해주셨어요. 직원분들도 친절해서 안심하고 이사했습니다.', TRUNC(SYSDATE) + -157 + 20/24 + 10/1440, '소중한 후기 감사합니다. 앞으로도 안전하고 꼼꼼한 이사 서비스로 보답하겠습니다.', TRUNC(SYSDATE) + -155, 900001);
