INSERT INTO TBL_REVIEW (REVIEW_ID, RESERVATION_ID, RATING, CONTENT, CREATED_AT, REPLY_CONTENT, REPLIED_AT, ADMIN_ID) VALUES (900003, 900003, 5, '보관 상태도 좋았고 다시 배송받을 때 파손된 물건 없이 잘 도착했어요.', TRUNC(SYSDATE) + -167 + 20/24 + 10/1440, NULL, NULL, NULL);
INSERT INTO TBL_REVIEW (REVIEW_ID, RESERVATION_ID, RATING, CONTENT, CREATED_AT, REPLY_CONTENT, REPLIED_AT, ADMIN_ID) VALUES (900004, 900004, 4, '전체적으로 괜찮았지만 도착 시간이 조금 늦어 아쉬웠습니다.', TRUNC(SYSDATE) + -172 + 20/24 + 10/1440, '소중한 후기 감사합니다. 앞으로도 안전하고 꼼꼼한 이사 서비스로 보답하겠습니다.', TRUNC(SYSDATE) + -170, 900001);
