INSERT INTO TBL_REVIEW (REVIEW_ID, RESERVATION_ID, RATING, CONTENT, CREATED_AT, REPLY_CONTENT, REPLIED_AT, ADMIN_ID) VALUES (900006, 900006, 5, '상담부터 이사 완료까지 안내가 정확하고 친절했어요.', TRUNC(SYSDATE) + -178 + 20/24 + 10/1440, '소중한 후기 감사합니다. 앞으로도 안전하고 꼼꼼한 이사 서비스로 보답하겠습니다.', TRUNC(SYSDATE) + -178, 900001);
