-- 샘플 지우기: ID 900000 이상인 샘플 행과, 샘플 행을 참조하는 행만 지움 (자식 → 부모 순)
DELETE FROM TBL_REVIEW_PHOTO WHERE PHOTO_ID >= 900000 OR REVIEW_ID IN (SELECT REVIEW_ID FROM TBL_REVIEW WHERE REVIEW_ID >= 900000 OR RESERVATION_ID >= 900000);
DELETE FROM TBL_REVIEW WHERE REVIEW_ID >= 900000 OR RESERVATION_ID >= 900000 OR ADMIN_ID >= 900000;
DELETE FROM TBL_SCHEDULE WHERE SCHEDULE_ID >= 900000 OR MEMBER_ID >= 900000 OR RESERVATION_ID >= 900000 OR ADMIN_ID >= 900000;
DELETE FROM TBL_RESERVATION WHERE RESERVATION_ID >= 900000 OR REQUEST_ID >= 900000;
DELETE FROM TBL_QUOTE_OPTION WHERE QT_OPTION_ID >= 900000 OR QUOTE_ID IN (SELECT QUOTE_ID FROM TBL_QUOTE WHERE QUOTE_ID >= 900000 OR REQUEST_ID >= 900000 OR MEMBER_ID >= 900000);
DELETE FROM TBL_QUOTE_ITEM WHERE QT_ITEM_ID >= 900000 OR QUOTE_ID IN (SELECT QUOTE_ID FROM TBL_QUOTE WHERE QUOTE_ID >= 900000 OR REQUEST_ID >= 900000 OR MEMBER_ID >= 900000);
DELETE FROM TBL_QUOTE WHERE QUOTE_ID >= 900000 OR REQUEST_ID >= 900000 OR MEMBER_ID >= 900000 OR ADMIN_ID >= 900000;
DELETE FROM TBL_REQUEST_ITEM WHERE RE_ITEM_ID >= 900000 OR REQUEST_ID >= 900000;
DELETE FROM TBL_RE_VIDEO WHERE VIDEO_ID >= 900000 OR REQUEST_ID >= 900000;
DELETE FROM TBL_MOVE_REQUEST WHERE REQUEST_ID >= 900000 OR MEMBER_ID >= 900000;
DELETE FROM TBL_CHAT_MESSAGE WHERE MESSAGE_ID >= 900000 OR ROOM_ID >= 900000 OR ADMIN_ID >= 900000 OR TOPIC_ID >= 900000;
DELETE FROM TBL_CHAT_ROOM WHERE ROOM_ID >= 900000 OR MEMBER_ID >= 900000 OR ADMIN_ID >= 900000;
DELETE FROM TBL_QUICK_MENU WHERE MENU_ID >= 900000 OR TOPIC_ID >= 900000 OR ADMIN_ID >= 900000;
DELETE FROM TBL_LOREBOOK WHERE LOREBOOK_ID >= 900000 OR TOPIC_ID >= 900000;
DELETE FROM TBL_CHATBOT_ACTION WHERE ACTION_ID >= 900000 OR TOPIC_ID >= 900000;
DELETE FROM TBL_CHATBOT_TOPIC WHERE TOPIC_ID >= 900000 OR ADMIN_ID >= 900000;
DELETE FROM TBL_CHAT_SETTING WHERE SETTING_ID >= 900000;
DELETE FROM TBL_SAVED_REPLY WHERE ADMIN_ID >= 900000;
DELETE FROM TBL_NOTIFICATION WHERE NOTIFICATION_ID >= 900000 OR MEMBER_ID >= 900000;
DELETE FROM TBL_NOTIFICATION_SETTING WHERE SETTING_ID >= 900000;
DELETE FROM TBL_CLOSED_DAY WHERE ADMIN_ID >= 900000;
DELETE FROM TBL_RESERVATION_SETTING WHERE ADMIN_ID >= 900000;
DELETE FROM TBL_SOCIAL WHERE MEMBER_ID >= 900000;
DELETE FROM TBL_MEMBER WHERE MEMBER_ID >= 900000;
DELETE FROM TBL_ADMIN WHERE ADMIN_ID >= 900000;
COMMIT;

